&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차 및 안내 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 절차&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류전형 - 전화면접 - 대면(화상)면접 – 최종 합격&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형절차는 직무별로 다르게 운영될 수 있으며, 일정 및 상황에 따라 변동될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;전형 일정 및 결과는 지원서에 등록하신 이메일로 개별 안내 드립니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;참고 사항&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;본 공고는 모집 완료 시 조기 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;지원서 내용 중 허위사실이 있는 경우에는 합격이 취소될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;취업 보호 대상자(보훈대상자, 장애인 등)는 관련 법률에 따라 채용우대를 받을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;직급과 담당 업무 범위는 후보자의 전반적인 경력과 경험 등 제반사정을 고려하여 변경될 수 있습니다. 이러한 변경이 필요할 경우, 최종 합격 통지 전 적절한 시기에 후보자와 커뮤니케이션 될 예정입니다.&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;채용 및 업무 수행과 관련하여 요구되는 법령상 자격이 갖추어지지 않은 경우 채용이 제한될 수 있습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;7&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;고용형태는 정규직으로 수습기간 12 주를 포함합니다. 단, 업무상 필요한 경우에는 상기 수습기간을 적용하지 않거나 단축 또는 연장할 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;개인정보 처리방침&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;12&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;쿠팡 그룹은 입사지원자 개인정보 처리방침(아래 링크)에 따라 귀하의 개인정보를 수집하여 처리합니다. &lt;/span&gt;&lt;a href=&quot;https://www.coupang.jobs/kr/privacy-policy/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;https://www.coupang.jobs/kr/privacy-policy&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;서류 반환 정책&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;1. 본 고지는 『채용절차의공정화에관한법률』 제 11 조제 6 항에 따른 것 입니다.&lt;br&gt;2. 당사 채용에 응시한 구직자 중 최종 합격이 되지 못한 구직자는 『채용절차의 공정화에 관한 법률』에 따라 제출한 채용서류의 반환을 청구할 수 있음을 알려 드립니다. 다만, 홈페이지 또는 전자우편으로 제출된 경우나 구직자가 당사의 요구 없이 자발적으로 제출한 경우에는 그러하지 아니하며, 천재지변이나 그 밖에 당사에게 책임 없는 사유로 채용서류가 멸실된 경우에는 반환한 것으로 봅니다.&lt;br&gt;3. 위 2 항 본문에 따라 채용 서류 반환 청구를 하는 구직자는 채용 서류 반환 청구서 [채용절차의 공정화에 관한 법률 시행규칙 별지 제 3 호 서식]를 작성하여 이메일 (recruitingops@coupangfs.com) 로 제출하면, 제출이 확인된 날로부터 14 일 이내에 지정한 주소지로 등기우편을 통하여 발송해 드립니다. 이 경우 등기우편요금은 수신자 부담으로 하게 되오니 유념하시기 바랍니다.&lt;br&gt;4. 당사는 위 2 항 본문에 따른 구직자의 반환 청구에 대비하여 채용 여부가 확정된 날로부터 180 일간 구직자가 제출한 채용서류 원본을 보관하게 되며, 그때까지 채용서류의 반환을 청구하지 아니할 경우에는 『개인정보 보호법』에 따라 지체 없이 채용서류 일체를 파기할 예정입니다.&lt;br&gt;5. 단, 위 1 항 내지 4 항의 내용은 대한민국의 노동 관계 법령이 적용되는 경우에만 적용됩니다. 그 이외의 경우에는 적용되지 않습니다.&lt;/span&gt;&lt;/p&gt;

anthemis-matic:greenhouse:5758842004.descriptionHtml:
&lt;p&gt;&lt;strong&gt;The Importance of this Role&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We&#39;re looking for a &lt;strong&gt;Senior&lt;/strong&gt; &lt;strong&gt;Customer Service Representative &lt;/strong&gt;to be the voice of Matic! Your job is to keep our customers happy by providing top-notch service. You will work directly with customers over the phone to answer questions, resolve concerns, and ensure they stay with Matic for the long haul.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Frontline Support:&lt;/strong&gt; Provide expert service and guidance to our customers primarily over the phone, as well as email and text.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Retention:&lt;/strong&gt; Identify customers at risk of cancellation and use problem-solving skills to retain their business&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Value Articulation:&lt;/strong&gt; Clearly articulate the Matic value proposition to reinforce why the customer chose us.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Upselling:&lt;/strong&gt; Offer other insurance products (bundling) to our customers where applicable to increase their coverage and value.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Goal Achievement:&lt;/strong&gt; Achieve team goals for productivity, quality, client satisfaction) and policy retention.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Our Expectations of an Inbound CSR:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Save Attempt EVERY TIME:&lt;/strong&gt; We require a save attempt to be made on every cancellation request.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;One Call Resolution:&lt;/strong&gt; Do everything you can to solve the issue before ending the call.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Customer Holds:&lt;/strong&gt; Inform customers they are being placed on hold. Check in every minute at a minimum to update.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We Champion Our Customers:&lt;/strong&gt; Every call and every interaction. Be proactive and if something is not right, own it.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Professionalism:&lt;/strong&gt; Be calm, professional, and empathetic. Represent the company as you would want your company represented.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Good, Better, Best:&lt;/strong&gt; Don’t settle. Look for ways to improve daily.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;1+ year of Customer Service experience (phone-based).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Effective verbal communication skills&lt;/strong&gt; with a talent for de-escalation and empathy.&lt;/li&gt;
&lt;li&gt;Tenacity and persuasiveness—you must be comfortable attempting to &quot;save&quot; a customer who wants to cancel.&lt;/li&gt;
&lt;li&gt;Ability to multitask: listening and responding to the customer while using a computer to research and enter information.&lt;/li&gt;
&lt;li&gt;Passion that can convey the value of our Matic message clearly.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What We Offer&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;We offer a competitive base hourly rate of $19.23 to $20.19&lt;/li&gt;
&lt;li&gt;You have an ownership stake - all Maticians receive Matic stock options.&lt;/li&gt;
&lt;li&gt;Unlimited Paid Time Off.&lt;/li&gt;
&lt;li&gt;Company covered Health, Dental &amp;amp; Vision insurance for each Matician ($0 out of your paycheck for benefits), plus HSA with employer contribution.&lt;/li&gt;
&lt;li&gt;401(k) Retirement Plan.&lt;/li&gt;
&lt;li&gt;Continuing education, licensing and professional development paid for by Matic.&lt;/li&gt;
&lt;li&gt;Career advancement - we have a culture that focuses on internal promotion and career growth.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A TRUE team culture -&amp;nbsp; One team, one dream is our company motto and while we are working hard to simplify the world of insurance, we never forget to play hard as well - we pride ourselves on frequent team events like happy hours, game nights, volleyball/kickball teams, etc!&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Modern office environment (that’s CDC compliant!) - we have a trendy HQ in the heart of German Village in downtown Columbus with awesome amenities including ping pong tables, coffee/espresso bar, flavored water bar (sparkling or still, your choice!).&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About Matic&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Matic is a startup with ample opportunities for growth. Since 2014, Matic has changed the landscape of the insurtech industry by integrating insurance within the home and auto ownership experience. Today, Matic’s digital insurance marketplace has over 50 A-rated home and auto carriers, as well as distribution partners in industries ranging from mortgage origination and servicing to banking, auto financing, and much more.&lt;/p&gt;
&lt;p&gt;We hire rock stars who are passionate about owning their work and are obsessed with finding a better way. Working at Matic means working collaboratively towards one common goal; we are one team with one dream. We have a fast-paced culture that is driven by quality, transparency, and of course fun.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Applicants must be currently authorized to work in the United States on a full-time basis now and in the future. This position does not offer sponsorship.&lt;/p&gt;

atlasventure-disc-medicine:greenhouse:50.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;em&gt;Join our team in a dynamic hybrid role, offering flexibility to work remotely and from our headquarters in Watertown, MA.&amp;nbsp; &lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;COMPANY OVERVIEW:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Disc Medicine is a clinical-stage biopharmaceutical company committed to discovering, developing, and commercializing novel treatments for patients who suffer from serious hematologic diseases. We are building a portfolio of innovative, first-in-class therapeutic candidates that aim to address a wide spectrum of hematologic diseases by targeting fundamental biological pathways of red blood cell biology, specifically heme biosynthesis and iron homeostasis. Disc Medicine values collaboration, professional development, and scientific integrity and promotes an inclusive company culture that empowers and inspires.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;POSITION OVERVIEW&lt;/strong&gt;&lt;strong&gt;:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Reporting to Executive Director, Biologics Drug Product; the Principal Scientist / Associate Director in Biologics Drug Product Development will be responsible for providing leadership for drug product technical elements of assets within the biologics pipeline programs, focusing on antibodies and/or proteins. The technical elements of this role may be responsible encompass biologics formulation development, drug product process development, technology transfer and manufacturing support, as well as development of subcutaneous delivery devices. This role will also be expected to contribute to authoring early and late-stage clinical filings as well as commercial filings. This position requires significant hands-on industry experience in the biologics formulation and drug product process development and manufacturing support areas, with a focus on antibodies and proteins.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;RESPONSIBILITIES:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Provide leadership to multiple technical elements of drug product development for Disc Medicine’s biologic drug product programs.&lt;/li&gt;
&lt;li&gt;Lead selected clinical and/or commercial formulation studies for antibody and/or biologics programs.&lt;/li&gt;
&lt;li&gt;Lead drug product process development and characterization activities for selected unit operations supporting early and/or late-stage clinical programs up to and including process performance qualification batches (PPQ).&lt;/li&gt;
&lt;li&gt;If necessary, participate in selecting and recommending appropriate external providers (CMOs/CROs), to support formulation and fill/finish process development.&lt;/li&gt;
&lt;li&gt;Provide significant technical leadership to drug product process transfers to CMOs as well as oversee drug product formulation, process development, and manufacturing at contract development and manufacturing organizations (CDMO)s.&lt;/li&gt;
&lt;li&gt;Provide expertise across various areas of biologics drug product development, such as in-use compatibility, extractables/leachables, and filter validation studies.&lt;/li&gt;
&lt;li&gt;As necessary, contribute to device selection, design control, and/or validation activities for subcutaneous delivery systems, such as pre-filled syringes, needle safety devices, and/or autoinjectors.&lt;/li&gt;
&lt;li&gt;Form effective relationships and collaborate well with the CMC leader(s) and CMC functions, including drug substance, analytical development, quality control, supply chain, and quality and regulatory organizations.&lt;/li&gt;
&lt;li&gt;Contributed to the budget management of assigned programs.&lt;/li&gt;
&lt;li&gt;Engage with CMC and/or Executive Leadership, as appropriate, to proactively identify and communicate technical risks and provide scientific recommendations for mitigation plans.&lt;/li&gt;
&lt;li&gt;Contribute to a positive workplace culture that prioritizes collaboration, ensures accountability, and a commitment to continuous improvement.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&amp;nbsp;REQUIREMENTS:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;A BS/MS in Chemical Engineering, Pharmaceutical Sciences, or similar areas is required.&lt;/li&gt;
&lt;li&gt;10-15 years in the pharmaceutical / biopharmaceutical industry with a minimum of 4-6 years of hands-on experience with early and/or late-stage drug product development programs, such as formulation, process, and/or device development and technology transfer.&lt;/li&gt;
&lt;li&gt;Knowledgeable in sterile drug product development, technology transfer, and manufacturing.&lt;/li&gt;
&lt;li&gt;Experience in formulation development of antibody products through various stages of the product lifecycle, including first in human through to commercial formulations.&lt;/li&gt;
&lt;li&gt;Experience in contributing to the authoring drug product sections of early and late-stage clinical filings, as well as commercial filings, is highly preferred.&lt;/li&gt;
&lt;li&gt;Strong ability to communicate well with cross-functional groups, including Drug Substance, Analytical Development, Quality, Regulatory, and Program Management.&lt;/li&gt;
&lt;li&gt;Significant experience working within CMC teams and with CMC team leaders.&lt;/li&gt;
&lt;li&gt;Prior experience working with domestic and international CDMOs for development and GMP manufacturing activities, including person in plant support.&lt;/li&gt;
&lt;li&gt;Ability to contribute to high-performing teams, including exceptional communication as well as fostering cross-functional teamwork.&lt;/li&gt;
&lt;li&gt;Excellent collaboration and interpersonal skills with ability to convey complex ideas succinctly.&lt;/li&gt;
&lt;li&gt;Travel of 20-30% may be required.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The annual base salary range for this position is listed below. Actual pay rates are determined by considering multiple factors including qualifications, relevance of experience, education &amp;amp; credentials, subject matter expertise, and internal parity.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$167,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$205,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Disc Medicine is an equal-opportunity employer committed to providing all qualified candidates and employees equal opportunities. We offer comprehensive benefits and competitive compensation packages. The Company headquarters are in Watertown, MA, and we provide a flexible work environment.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Disc Medicine actively recruits individuals with an entrepreneurial spirit and a drive for excellence. Interested candidates should submit their resume to be considered for current and future opportunities.&lt;/p&gt;
&lt;p&gt;Disc Medicine respects your privacy.&amp;nbsp; For information about how Disc processes your personal data in the context of your candidacy, please see our&amp;nbsp;&lt;a href=&quot;https://nam04.safelinks.protection.outlook.com/?url=https%3A%2F%2Fwww.discmedicine.com%2Fwp-content%2Fuploads%2F2025%2F06%2FPrivacyNotice_Final.pdf&amp;amp;data=05%7C02%7Cedomann%40discmedicine.com%7Cd1d721d1a5eb43f683f108de4ed273ff%7C6deedf28ffbe4ca88c8985f256117dc6%7C1%7C0%7C639034862964186947%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;amp;sdata=rVgNWYR6Rq2ayA3M1wMMAXbW3%2FDFE1SYvsXsfsvYmII%3D&amp;amp;reserved=0&quot;&gt;Privacy Notice&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;

atomico-attentive-mobile:greenhouse:4244.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;div&gt;Attentive® is the AI marketing platform for 1:1 personalization redefining the way brands and people connect. We’re the only marketing platform that combines powerful technology with human expertise to build authentic customer relationships. By unifying SMS, RCS, email, and push notifications, our AI-powered personalization engine delivers bespoke experiences that drive performance, revenue, and loyalty through real-time behavioral insights.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Recognized as the&amp;nbsp;#1&amp;nbsp;provider in SMS Marketing by G2, Attentive partners with more than 8,000 customers across 70+ industries. Leading global brands like Crate and Barrel, Urban Outfitters, and Carter’s work with us to enable billions of interactions that power tens of billions in revenue for our customers.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;With a distributed global workforce and employee hubs in New York City, San Francisco, London, and Sydney, Attentive’s team has been consistently recognized for its performance and culture. We’re proud to be included in&amp;nbsp;&lt;a href=&quot;https://www.deloitte.com/content/dam/assets-zone3/us/en/docs/services/deloitte-private/2025/us-2024-technology-fast-500-rankings.pdf&quot;&gt;Deloitte’s Fast 500&lt;/a&gt;&amp;nbsp;(four years running!),&amp;nbsp;&lt;a href=&quot;https://www.attentive.com/blog/attentive-ranked-8-on-linkedins-2020-top-startups-list-in-the-united-states&quot;&gt;LinkedIn’s Top Startups&lt;/a&gt;,&amp;nbsp;&lt;a href=&quot;https://www.forbes.com/lists/cloud100/&quot;&gt;Forbes’ Cloud 100&lt;/a&gt; (five years running!),&amp;nbsp;&lt;a href=&quot;https://www.inc.com/best-workplaces/2025&quot;&gt;Inc.’s Best Workplaces&lt;/a&gt;, and the&amp;nbsp;&lt;a href=&quot;https://www.hrc.org/resources/corporate-equality-index&quot; target=&quot;_blank&quot;&gt;Human Rights Campaign Foundation&#39;s Corporate Equality Index&lt;/a&gt;!&lt;/div&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the Role&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Our Machine Learning Engineering team powers personalized experiences for hundreds of millions of customers across thousands of brands. As a Senior Machine Learning Engineer, you will play a critical role in building, scaling, and operating production-grade ML systems that drive real-time personalization across the Attentive platform.&lt;/p&gt;
&lt;div&gt;You will operate with a high degree of ownership, partner closely with Product and Engineering, and help raise the technical bar across our ML systems in a fast-paced, high-impact environment.&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Accomplish&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You have a proven track record of building systems that maintain a high bar of quality&lt;/li&gt;
&lt;li&gt;You deeply loathe regressions and take proactive steps to protect against them through a variety of testing techniques&lt;/li&gt;
&lt;li&gt;You are a collaborator, technical leader, and a great communicator&lt;/li&gt;
&lt;li&gt;You are constantly improving the quality of the project you are working on, both via direct contributions as well as long-term advocacy for larger-scale changes&lt;/li&gt;
&lt;li&gt;You are enthusiastic about the high impact, fast-paced work environment of an late-stage startup&lt;/li&gt;
&lt;li&gt;10+ years experience is ideal&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Your Expertise&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;b3546ed4 bdf2b465&quot;&gt;
&lt;li&gt;You have worked professionally building systems for 6+ years with experience on a single system long enough to see the consequences of your decisions&lt;/li&gt;
&lt;li&gt;Experience with TensorFlow/Pytorch, xgboost, pandas, matplotlib, SQL, Spark or similar tools&lt;/li&gt;
&lt;li&gt;You have proficiency or experience with Python&lt;/li&gt;
&lt;li&gt;You have extensive experience using machine learning and data analysis, or similar, to build scalable systems and data-driven products, working with cross-functional teams&lt;/li&gt;
&lt;li&gt;You have a proven track record of building scalable, efficient, automated processes for large-scale data analyses, model development, model validation, and model implementation from modern research&lt;/li&gt;
&lt;li&gt;You have led cross-functional machine learning projects across teams&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What We Use &lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;b3546ed4 bdf2b465&quot;&gt;
&lt;li&gt;Our infrastructure runs primarily in Kubernetes hosted in AWS’s EKS&lt;/li&gt;
&lt;li&gt;Infrastructure tooling includes Istio, Datadog, Terraform, CloudFlare, and Helm&lt;/li&gt;
&lt;li&gt;Our backend is Java / Spring Boot microservices, built with Gradle, coupled with things like DynamoDB, Kinesis, AirFlow, Postgres, Planetscale, and Redis, hosted via AWS&lt;/li&gt;
&lt;li&gt;Our frontend is built with React and TypeScript, and uses best practices like GraphQL, Storybook, Radix UI, Vite, esbuild, and Playwright&lt;/li&gt;
&lt;li&gt;Our automation is driven by custom and open source machine learning models, lots of data and built with Python, Metaflow, HuggingFace 🤗, PyTorch, TensorFlow, and Pandas&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You&#39;ll get competitive&lt;a href=&quot;https://www.attentive.com/benefits&quot;&gt;&amp;nbsp;perks and benefits&lt;/a&gt;, from health &amp;amp; wellness to equity, to help you bring your best self to work.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;For US based applicants:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;The US base salary range for this full-time position is $320,000 - $360,000 annually&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;+ equity + benefits&lt;/li&gt;
&lt;li&gt;Our salary ranges are determined by role, level and location&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;#LI-EF1&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;strong&gt;By applying for this position, your data will be processed as per &lt;a href=&quot;https://drive.google.com/file/d/1RViE_YUnu0ipiJQ9xDpC-iSJ9sYJBbX8/view?usp=sharing&quot; target=&quot;_blank&quot;&gt;Attentive&#39;s Privacy Policy&lt;/a&gt;.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&lt;strong&gt;Attentive Company Values&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Default to Action&lt;/strong&gt; - Move swiftly and with purpose&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Be One Unstoppable Team&lt;/strong&gt; - Rally as each other’s champions&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Champion the Customer &lt;/strong&gt;- Our success is defined by our customers&#39; success&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Act Like an Owner&lt;/strong&gt;&amp;nbsp;- Take responsibility for Attentive’s success&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Learn more about &lt;a class=&quot;postings-link&quot; href=&quot;https://www.attentive.com/awake&quot;&gt;AWAKE&lt;/a&gt;, Attentive’s collective of employee resource groups.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;If you do not meet all the requirements listed here, we still encourage you to apply! No job description is perfect, and we may also have another opportunity that closely matches your skills and experience.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;At Attentive, we know that our Company&#39;s strength lies in the diversity of our employees. Attentive is an Equal Opportunity Employer and we welcome applicants from all backgrounds. Our policy is to provide equal employment opportunities for all employees, applicants and covered individuals regardless of protected characteristics. We prioritize and maintain a fair, inclusive and equitable workplace free from discrimination, harassment, and retaliation. Attentive is also committed to providing reasonable accommodations for candidates with disabilities. If you need any assistance or reasonable accommodations, please let your recruiter know.&amp;nbsp;&lt;/div&gt;&lt;/div&gt;

baincapital-hudl:greenhouse:7947590.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;At Hudl, we build great teams. We hire the best of the best to ensure you’re working with people you can constantly learn from. You’re trusted to get your work done your way while testing the limits of what’s possible and what’s next. We work hard to provide a culture where everyone feels supported, and our employees feel it—their votes helped us become one of &lt;a href=&quot;https://www.hudl.com/blog/newsweek-top-100-global-most-loved-workplaces-2023&quot;&gt;Newsweek&#39;s Top 100 Global Most Loved Workplaces&lt;/a&gt;.&amp;nbsp;&amp;nbsp;&lt;br&gt;&lt;br&gt;We think of ourselves as the team behind the team, supporting the lifelong impact sports can have: the lessons in teamwork and dedication; the influence of inspiring coaches; and the opportunities to reach new heights. That’s why we help teams from all over the world see their game differently. Our products make it easier for coaches and athletes at any level to capture video, analyze data, share highlights and more.&lt;br&gt;&lt;br&gt;Ready to join us?&lt;/p&gt;
&lt;div style=&quot;padding: 56.25% 0 0 0; position: relative;&quot;&gt;&lt;iframe style=&quot;position: absolute; top: 0; left: 0; width: 100%; height: 100%; border: 0;&quot; src=&quot;https://player.vimeo.com/video/1095624224?h=9e8cdc9dbe&amp;amp;badge=0&amp;amp;autopause=0&amp;amp;player_id=0&amp;amp;app_id=58479&quot; width=&quot;&quot; height=&quot;&quot;&gt;&lt;/iframe&gt;&lt;/div&gt;&lt;/div&gt;&lt;h2&gt;Your Role&lt;/h2&gt;
&lt;p&gt;We&#39;re hiring a &lt;strong&gt;Senior Design Researcher&lt;/strong&gt; to serve as the research expert for our Hardware business unit, which focuses on defining the future of automated capture and wearable technology. You&#39;ll combine deep methodological expertise across hardware and software with strong leadership skills to elevate research practices and connect insights directly to product outcomes.&lt;/p&gt;
&lt;p&gt;As a &lt;strong&gt;Senior Design Researcher&lt;/strong&gt;, you’ll:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Lead research for hardware.&lt;/strong&gt; You’ll be embedded within product teams, maintaining a direct connection to customers through interviews, usability studies and field research to ensure we’re building the right things.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Master your craft.&lt;/strong&gt; You’ll use a mix of qualitative and quantitative methodologies across hardware and software contexts, holding a high bar for quality while uncovering deep user needs that go beyond the obvious.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Empower the team.&lt;/strong&gt; You’ll guide cross-functional teams in creating research plans, mentoring other designers and sharing best practices to raise our collective capability.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Leverage modern tools.&lt;/strong&gt; You’ll use AI fluently to speed up synthesis and pattern recognition, helping us compress the feedback loop between customer contact and actionable product direction.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Collaborate and communicate.&lt;/strong&gt; You’ll work closely with Product Managers and designers to right-size research objectives and present findings through compelling storytelling and clear metrics.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;We&#39;d like to hire someone for this role who lives near our offices in Lincoln and Omaha, but we&#39;re also open to remote candidates in Kansas City, Chicago, Austin, or Dallas.&lt;/p&gt;
&lt;h2&gt;Must-Haves&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Experienced.&lt;/strong&gt; You have five or more years of experience as a design researcher in tech environments and a proven track record of connecting insights to design outcomes.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Insight-drive direction.&lt;/strong&gt; You excel at extracting critical contextual information about users, environments and tasks — and you&#39;re accountable for how effectively your insights address product obstacles and inform design decisions.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;AI-fluent.&lt;/strong&gt; You have a practiced point of view on how to use AI-assisted research tools to accelerate delivery without sacrificing rigor and quality.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;A strong communicator.&lt;/strong&gt; You’re excellent at visualization and storytelling, making complex data approachable for various audiences.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Mobile.&lt;/strong&gt; You’re willing to travel up to 20% of the time, both domestically and internationally, to conduct research and collaborate with your team.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Hardware background.&lt;/strong&gt;&amp;nbsp; You’ve mastered research methodologies across hardware, software, consumer electronics and/or hard goods. You have strong qualitative and quantitative research skills across various approaches including focus groups, in-depth interviews, usability testing, field studies and prototype evaluations.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Nice-to-Haves&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Educational background.&lt;/strong&gt; You have an advanced degree in HCI, Human Factors, Cognitive Psychology or a related field.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Software experience.&lt;/strong&gt; You&#39;ve worked with software product teams and understand the unique research requirements in digital product development.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Our Role&lt;/h2&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Champion work-life harmony&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;. We’ll give you the flexibility you need in your work life (e.g., flexible vacation time, company-wide holidays and timeout (meeting-free) days, remote work options and more) so you can enjoy your personal life too.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Guarantee autonomy&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;. We have an open, honest culture and we trust our people from day one. Your team will support you, but you’ll own your work and have the agency to try new ideas.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Encourage career growth&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;. We’re lifelong learners who encourage professional development. We’ll give you tons of resources and opportunities to keep growing.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Provide an environment to help you succeed&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;. We&#39;ve invested in our offices, designing incredible spaces with our employees in mind. But whether you’re at the office or working remotely, we’ll provide you the tech stack and hardware to do your best work.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Support your mental and physical health&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;. We care about our employees’ wellbeing. Our Employee Assistance Program, employee resource groups and fitness partner Peerfit have you covered.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Cover your medical&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; &lt;/span&gt;&lt;strong&gt;insurance&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;. We have multiple plans to pick from to ensure you’ll have the coverage you (and your dependents) want, including vision, dental, fertility healthcare and family forming benefits.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Contribute to your 401(K)&lt;/strong&gt;. Yep, that’s free money. We’ll match up to 4% of your own contribution.&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Compensation&lt;/h2&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The base salary range for this role is displayed below—&lt;strong&gt;starting salaries will typically fall near the middle of this range.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We make compensation decisions based on an individual&#39;s experience, skills and education in line with our internal pay equity practices.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This role will also be eligible for a long-term incentive (LTI) award. Any bonuses awarded are based on individual and company performance paid at Hudl&#39;s discretion.&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Base Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$112,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$187,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h2&gt;&lt;strong&gt;Inclusion at Hudl&amp;nbsp;&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;Hudl is an equal opportunity employer. Through our actions, behaviors and attitude, we’ll create an environment where everyone, no matter their differences, feels like they belong.&amp;nbsp;&lt;br&gt;&lt;br&gt;We offer resources to ensure our employees feel safe bringing their authentic selves to work, &lt;a href=&quot;https://www.hudl.com/about-inclusion&quot; target=&quot;_blank&quot;&gt;including employee resource groups and communities&lt;/a&gt;. But we recognize there’s ongoing work to be done, which is why we track our efforts and commitments in &lt;a href=&quot;https://www.hudl.com/about-inclusion&quot; target=&quot;_blank&quot;&gt;annual inclusion reports&lt;/a&gt;.&amp;nbsp;&lt;br&gt;&lt;br&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We also know imposter syndrome is real and the &lt;a href=&quot;https://www.theatlantic.com/magazine/archive/2014/05/the-confidence-gap/359815/&quot; target=&quot;_blank&quot;&gt;confidence gap&lt;/a&gt; can get in the way of meeting spectacular candidates. Please don’t hesitate to apply—we’d love to hear from you.&lt;/span&gt;&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;Privacy Policy&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;https://www.hudl.com/jobs/hudl-applicant-and-candidate-privacy-policy&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Hudl Applicant and Candidate Privacy Policy&lt;/span&gt;&lt;/a&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;

baincapitalventures-justworks:greenhouse.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h1&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Justworks, you’ll enjoy a welcoming and casual environment, great benefits, wellness program offerings, company retreats, and the ability to interact with and learn from leaders in the startup community. We work hard and care about our most prized asset - our people.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We’re helping businesses get off the ground by enabling them to focus on running their business. We solve HR issues. We’re data-driven and never stop iterating. If you’d like to work in a supportive, entrepreneurial environment, are interested in building something meaningful and having fun while doing it, we’d love to hear from you.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We&#39;re united by shared goals and shared motivations at Justworks. These are best summed up in our company values, which are reflected in our product and in our team.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.justworks.com/careers#values&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our Values&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;If this sounds like you, you’ll fit right in.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;h1&gt;&lt;strong&gt;Who You Are&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;As an experienced leader on our Customer Support team, you will be responsible for guiding your team of Customer Support Payments Specialists as they expertly handle a high volume of customer payments inquiries across multiple channels. In this role, you will focus on keeping work quality high and response times speedy as the company and our customer base grows. Along the way, it&#39;s key that you collect and prioritize common requests and needs from our customers and their employees to help Justworks improve.&lt;/p&gt;
&lt;p&gt;We are looking for a hands-on leader, who will think and act both strategically and tactically, to drive the team’s engagement at all points of the customer lifecycle. You should be an enthusiastic and creative individual with the ability to inspire others, as you will be responsible for coaching, mentoring and developing individual team members.&lt;/p&gt;
&lt;h1&gt;&lt;strong&gt;Your Success Profile&lt;/strong&gt;&lt;/h1&gt;
&lt;h2&gt;&lt;strong&gt;What You Will Work On&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Lead a team of Customer Support Payments Specialists who assist our customers with inbound support inquiries across multiple channels&lt;/li&gt;
&lt;li&gt;Form a tight cross-functional relationship with key stakeholders across PTU, Legal, RevEn, and Security to ensure seamless interactions and alignment of goals and initiatives&lt;/li&gt;
&lt;li&gt;Create and present a quarterly root cause analysis to report on payments and tax trends and insights to senior leadership&lt;/li&gt;
&lt;li&gt;Recommend improvements to payments and tax products, features, and processes as a result of data-backed insights and analysis&lt;/li&gt;
&lt;li&gt;Ownership and accountability of the NSF process and collection for Support-owned customers&lt;/li&gt;
&lt;li&gt;Assist with resolving customer critical moments and turning a customer’s negative experience into a positive one&lt;/li&gt;
&lt;li&gt;Understanding customer needs related to payments and trends, and ability to make recommendations to improve customer outcomes&lt;/li&gt;
&lt;li&gt;Contribute to the development and implementation of Payments Specialist training&lt;/li&gt;
&lt;li&gt;Obsess over customer satisfaction and set clear expectations with your team for what successful customer interactions look like&lt;/li&gt;
&lt;li&gt;Own and publish key metrics for your team such as response time, productivity, CSAT, QA, and utilization&lt;/li&gt;
&lt;li&gt;Work closely with the Talent Acquisition and Training teams to evaluate and successfully onboard and ramp new employees&lt;/li&gt;
&lt;li&gt;Handle general management responsibilities, such as leading regular team meetings, individual one-on-ones, generating weekly metrics reports, quarterly business reviews, and conducting periodic performance reviews&lt;/li&gt;
&lt;li&gt;Other duties as needed based on department and/or organizational needs&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;How You Will Do Your Work&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;As a Manager of Customer Support, &lt;em&gt;how&lt;/em&gt; results are achieved is paramount for your success and ultimately result in our success as an organization. In this role, your foundational knowledge, skills, abilities and personal attributes are anchored in the following:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Builds an Effective Team -&amp;nbsp; &lt;/strong&gt;Building a strong-identity team that applies their diverse skills and perspectives to achieve common goals&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Develops Talent -&lt;/strong&gt;&amp;nbsp; Developing people to meet both their career goals and the organization’s goals through effective performance management, candid feedback and coaching conversations&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Cultivates Innovation -&lt;/strong&gt;&lt;strong&gt;&lt;em&gt; &lt;/em&gt;&lt;/strong&gt;Inspires creativity and curiosity, pushes beyond comfort zone, prioritizes learning &amp;amp; development for self and team&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Ensures Accountability - &lt;/strong&gt;Holds self and others accountable to meet commitments&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Directs work -&lt;/strong&gt;&amp;nbsp; Providing direction, delegating and removing obstacles to get work done&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;In addition, all Justworkers focus on aligning their behaviors to our core values known as COGIS. It stands for:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Camaraderie&lt;/strong&gt;&amp;nbsp;- Day to day you can be seen working together toward a higher purpose. You like to have fun. You’re an active listener, treat people respectfully, and have a strong desire to know and help others.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Openness&lt;/strong&gt;&amp;nbsp;- Your default is to be open. You&#39;re willing to share information, understand other perspectives, and consider new possibilities. You’re curious, ask open questions, and are receptive to thoughts and feedback from others.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Grit&amp;nbsp;&lt;/strong&gt;- You demonstrate grit by having the courage to commit and persevere. You’re committed, earnest, and dive in to get the job done well with a positive attitude.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Integrity&lt;/strong&gt;&amp;nbsp;- Simply put, do what you say and say what you&#39;ll do. You’re honest and forthright, have a strong moral compass, and strive to match your words with your actions while leading by example.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Simplicity&lt;/strong&gt;&amp;nbsp;- Be like Einstein: “Everything should be made as simple as possible, but no simpler.”&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Qualifications&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;4 year degree or equivalent relevant work experience3+ years managing a customer service team, preferably in the payments or payroll space&lt;/li&gt;
&lt;li&gt;Expert level knowledge of&amp;nbsp; payroll processing and payroll tax across PEO and non-PEO products&lt;/li&gt;
&lt;li&gt;Passion for helping customers and Superior customer support skills - ability to be empathetic, compassionate, responsive and resourceful&lt;/li&gt;
&lt;li&gt;Advanced experience and skill with mentoring and coaching Proficiency with CRM and customer service communication platforms&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience identifying service trends and creating a path to resolve them&lt;/li&gt;
&lt;li&gt;Self-driven to be productive and seek out self-improvement&lt;/li&gt;
&lt;li&gt;Genuine desire to improve the quality of service we provide as well as the experience of our team members&lt;/li&gt;
&lt;li&gt;Comfort and experience leading a team through effective change management and stressful situations&lt;/li&gt;
&lt;li&gt;Strong written and verbal communication skills with acute attention to detail&lt;/li&gt;
&lt;li&gt;Aptitude for learning new products and helping to break down complicated topics and explain them in simple terms people can understand&lt;/li&gt;
&lt;li&gt;Ability to come up with creative solutions to any problem you face, and know-how to organize and prioritize your workload&lt;/li&gt;
&lt;li&gt;Excited to be a part of a team that supports customers 24/7&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;The base wage range for this position based in our Tampa Office is targeted at $111,600.00 to $122,760.00 per year.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;#LI-Hybrid #LI-KC2&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Actual compensation is based on multiple factors that are unique to each candidate, including and not limited to skill set, level of relevant experience, and specific work location.&amp;nbsp; &lt;/span&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Salary ranges for positions based in other locations may differ based on the cost of labor in that location.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;For more information about Justworks’ Total Reward Philosophy, including all of the perks and benefits we are proud to offer our team members, please visit &lt;/span&gt;&lt;a href=&quot;https://www.justworks.com/careers#total-reward-philosophy&quot;&gt;Total Rewards @ Justworks&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h1&gt;&lt;strong&gt;Diversity At Justworks&lt;/strong&gt;&lt;/h1&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Justworks is committed to maintaining a workplace where diversity of identity, culture, and life experience is the norm and is celebrated authentically and respected consistently. Diversity in our work, our people, and our product drives creativity and innovation, entrepreneurial leadership and integrity, competitiveness, and collaboration throughout our business and in the market. We depend on our differences to make our team stronger, our workplace more dynamic, and our product accessible to all of our customers.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;We’re proud to be an equal opportunity employer open to all qualified applicants regardless of race, color, ancestry, religion, sex, national origin, sexual orientation, age, citizenship, marital or familial status, disability, pregnancy, gender identity or expression, veteran status, genetic information, or any other legally protected status. Justworks is fully dedicated to providing necessary support to candidates with disabilities who may require reasonable accommodations. We also provide reasonable accommodations to employees based on their sincerely held religious beliefs, as well as for other covered reasons consistent with applicable federal, state, and local laws. If you&#39;re in need of a reasonable accommodation, please reach out to us at &lt;a href=&quot;mailto:accommodations@justworks.com&quot;&gt;accommodations@justworks.com&lt;/a&gt;. Your comfort and success matter to us, and we&#39;re here to ensure an inclusive experience.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.justworks.com/press/company-news/justworks-impact-report-2024&quot; target=&quot;_blank&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Our DEIB Report&amp;nbsp;&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;

baincapitalventures-maintainx:greenhouse.descriptionHtml:
&lt;p&gt;MaintainX est la plateforme la plus utilisée au monde en matière de gestion des actifs et d&#39;intelligence du travail pour les environnements industriels et de première ligne, avec plus de 13 000 clients dont Duracell, Shell, Cintas et Brenntag. Nous avons levé 150 millions de dollars lors de notre série D, menée par Bessemer Venture Partners et Bain Capital Ventures, portant notre financement total à 254 millions de dollars, et évaluant l’entreprise à 2,5 milliards de dollars. Nous figurons également au prestigieux classement Forbes Cloud 100 2025, qui répertorie les 100 meilleures entreprises infonuagiques privées à l&#39;échelle mondiale.&lt;/p&gt;
&lt;p&gt;Nous recherchons un concepteur de produits senior pour rejoindre notre équipe en pleine expansion et contribuer à façonner la prochaine génération de l&#39;expérience produit de MaintainX. À ce poste, vous dirigerez les efforts de conception tout au long du cycle de vie du produit, de la découverte et la recherche à la création de maquettes fonctionnelles, de prototypes et d&#39;interfaces utilisateur perfectionnées, tant pour les plateformes web que mobiles. Vous collaborerez étroitement avec les chefs de produit, les ingénieurs et d&#39;autres concepteurs afin de proposer des fonctionnalités qui rendent les systèmes complexes simples et intuitifs pour les utilisateurs non techniciens.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Ce que vous ferez :&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Vous rejoindrez une équipe pluridisciplinaire de concepteurs, de gestionnaires de produits et d&#39;ingénieurs, qui collaboreront à la définition du champ d&#39;application, à l&#39;idéation, au prototypage et à la livraison de conceptions utilisables et agréables pour répondre aux définitions du produit et aux objectifs de l&#39;entreprise.&lt;/li&gt;
&lt;li&gt;Vous serez impliqué dans le processus de développement de bout en bout, de la définition à la maintenance des fonctionnalités du produit, en passant par la conception, la construction, les tests et la mise en production.&lt;/li&gt;
&lt;li&gt;Vous présenterez votre travail à votre équipe et aux parties prenantes transversales, y compris les ventes, le marketing et la direction, en communiquant efficacement votre processus de prise de décision et en intégrant le retour d&#39;informations provenant de différents points de vue et besoins.&lt;/li&gt;
&lt;li&gt;Vous aidez à cultiver la culture de conception de l&#39;équipe et de l&#39;entreprise, y compris en défendant la pensée de conception centrée sur l&#39;utilisateur dans toutes nos initiatives et en maintenant un processus de conception collaboratif.&lt;/li&gt;
&lt;li&gt;Collaborer à la définition et à la documentation de notre système de conception, en collaborant avec d&#39;autres concepteurs et développeurs pour travailler et faire évoluer nos composants et mises en page actuels.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;A propos de vous :&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Plus de 6 ans d&#39;expérience dans la conception de produits, y compris dans le domaine du SaaS B2B ou des plateformes d&#39;entreprise.&lt;/li&gt;
&lt;li&gt;Compréhension approfondie des directives de conception de l&#39;interface humaine d&#39;Apple, de la conception d&#39;Android et d&#39;autres plates-formes mobiles, y compris la conception matérielle de Google.&lt;/li&gt;
&lt;li&gt;Connaissance pratique des outils de conception modernes (Figma).&lt;/li&gt;
&lt;li&gt;Vous disposez d&#39;un portfolio présentant des travaux de conception pertinents illustrant votre processus et votre contribution à des projets spécifiques.&lt;/li&gt;
&lt;li&gt;Vous avez un bon niveau d&#39;anglais pour parler et communiquer efficacement vos idées.&lt;/li&gt;
&lt;li&gt;Vous êtes flexible dans votre approche et acceptez les défis ; vous pouvez trouver de nouvelles façons de répondre rapidement à des questions de recherche et de communiquer les résultats d&#39;une manière mémorable et percutante.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Quels sont les avantages pour vous?:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Un salaire compétitif et des opportunités d&#39;équité significatives.&lt;/li&gt;
&lt;li&gt;Couverture des soins de santé, des soins dentaires et de la vue.&lt;/li&gt;
&lt;li&gt;Programme d&#39;inscription 401(k) / RRSP.&lt;/li&gt;
&lt;li&gt;Prenez les congés dont vous avez besoin.&lt;/li&gt;
&lt;li&gt;Une &lt;a href=&quot;https://crew.vc/perspectives-insights/scaling-culture-through-hyper-growth/&quot;&gt;culture&lt;/a&gt; du travail où :&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Vous travaillerez aux côtés de personnes du monde entier qui reflètent les valeurs de MaintainX : Intelligents, Humbles, Optimistes.&lt;/li&gt;
&lt;li&gt;Nous croyons en la méritocratie, où les idées et les efforts sont publiquement célébrés.&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qui sommes-nous:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Notre mission est de faciliter la vie des ouvriers dans le monde entier en créant des logiciels qui répondent à leurs besoins et à leurs réalités. Notre produit change véritablement la vie de 80% de la population active qui ne travaille pas derrière un bureau et qui a besoin d&#39;un logiciel d&#39;entreprise à portée de main.&lt;/p&gt;
&lt;p&gt;MaintainX s&#39;engage à créer un environnement diversifié. Tous les candidats qualifiés seront pris en considération pour un emploi sans considération de race, de couleur, de religion, de sexe, d&#39;identité ou d&#39;expression de genre, d&#39;orientation sexuelle, d&#39;origine nationale, de génétique, d&#39;invalidité, d&#39;âge ou de statut d&#39;ancien combattant.&lt;/p&gt;

&lt;p&gt;MaintainX est la plus importante plateforme au monde en matière de gestion des actifs et d&#39;intelligence du travail pour les environnements industriels et de première ligne. Nous sommes un outil moderne de type IdO et basé sur le réseau informatique en nuage pour la fiabilité, la sécurité et les opérations de l&#39;équipement physique et des installations. MaintainX alimente l&#39;excellence opérationnelle pour plus de 13 000 entreprises, notamment Duracell, Univar Solutions Inc, Titan America, McDonald&#39;s, Brenntag, Cintas, Xylem et Shell.&lt;/p&gt;
&lt;p&gt;Nous avons récemment conclu un financement de série D de 150 millions de dollars, portant notre financement total à 254 millions de dollars et évaluant l’entreprise à 2,5 milliards de dollars.&lt;/p&gt;
&lt;p&gt;Nous recherchons un analyste principal en sécurité pour soutenir notre programme de sécurité dans les environnements réglementés (FedRAMP) et non réglementés. Ce poste est axé sur les opérations de sécurité, la gestion des vulnérabilités et le soutien à la conformité. Vous travaillerez avec des outils tels que Datadog, Wiz et AWS pour protéger notre infrastructure et nos données dans plusieurs environnements.&lt;/p&gt;
&lt;p&gt;Ce poste est hybride et basé dans nos bureaux de Montréal.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Ce que vous ferez:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Surveiller et trier les alertes de sécurité à l&#39;aide d&#39;outils tels que Datadog, les plateformes SIEM et d&#39;autres solutions de surveillance de la sécurité.&lt;/li&gt;
&lt;li&gt;Gérer les programmes d&#39;évaluation des vulnérabilités, en suivant les efforts de correction dans l&#39;infrastructure cloud et sur site.&lt;/li&gt;
&lt;li&gt;Réaliser des évaluations des contrôles de sécurité et préparer la documentation technique et les preuves pour les audits.&lt;/li&gt;
&lt;li&gt;Soutenir les initiatives de tests d&#39;intrusion et les évaluations de sécurité sur les produits et l&#39;infrastructure internes.&lt;/li&gt;
&lt;li&gt;Enquêter sur les incidents de sécurité, documenter les conclusions et soutenir les activités de réponse aux incidents.&lt;/li&gt;
&lt;li&gt;Collaborer avec les équipes DevOps, informatiques, produits et autres pour mettre en œuvre et vérifier les contrôles de sécurité.&lt;/li&gt;
&lt;li&gt;Développer des outils pour l&#39;équipe de sécurité.&lt;/li&gt;
&lt;li&gt;Participer à des audits internes et externes dans le cadre de plusieurs référentiels de conformité (FedRAMP, SOC 2, ISO 27001, etc.).&lt;/li&gt;
&lt;li&gt;Contribuer à l&#39;élaboration de politiques de sécurité, à la documentation et aux initiatives de formation de sensibilisation.&lt;/li&gt;
&lt;li&gt;Se tenir au courant des nouvelles menaces, des meilleures pratiques en matière de sécurité et des exigences de conformité.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;À propos de vous:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Licence en cybersécurité, technologies de l&#39;information, informatique ou dans un domaine connexe (ou expérience équivalente).&lt;/li&gt;
&lt;li&gt;2 à 4 ans d&#39;expérience dans la sécurité de l&#39;information, les opérations de sécurité ou des fonctions connexes.&lt;/li&gt;
&lt;li&gt;Expérience pratique de la sécurité dans le cloud (principalement AWS) et des outils de sécurité natifs du cloud.&lt;/li&gt;
&lt;li&gt;Connaissance des cadres de sécurité tels que NIST 800-53, SOC 2, ISO 27001 ou FedRAMP.&lt;/li&gt;
&lt;li&gt;Expérience des outils et processus de gestion des vulnérabilités.&lt;/li&gt;
&lt;li&gt;Compréhension de la surveillance de la sécurité, de l&#39;analyse des journaux et de la réponse aux incidents.&lt;/li&gt;
&lt;li&gt;Solides compétences analytiques et de résolution de problèmes, avec le souci du détail.&lt;/li&gt;
&lt;li&gt;Excellentes compétences en communication écrite et orale.&lt;/li&gt;
&lt;li&gt;Capacité à travailler de manière autonome et collaborative dans un environnement en constante évolution.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Une attention particulière est accordée aux candidats présentant les caractéristiques suivantes:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience with security tools such as Wiz, Datadog, Jira, vulnerability scanners, password managers, EDRs and SIEM platforms.&lt;/li&gt;
&lt;li&gt;Previous experience supporting compliance programs (FedRAMP, SOC 2, ISO 27001, etc.).&lt;/li&gt;
&lt;li&gt;Security certifications such as Security+, GSEC, OSCP, CISSP, or equivalent.&lt;/li&gt;
&lt;li&gt;Experience with penetration testing methodologies and tools.&lt;/li&gt;
&lt;li&gt;Knowledge of DevSecOps practices and security automation.&lt;/li&gt;
&lt;li&gt;Scripting or programming experience (typescript, dot net) for security automation.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Quels sont les avantages pour vous?:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Un salaire compétitif et des opportunités d&#39;équité significatives.&lt;/li&gt;
&lt;li&gt;Couverture des soins de santé, des soins dentaires et de la vue.&lt;/li&gt;
&lt;li&gt;Programme d&#39;inscription 401(k) / RRSP.&lt;/li&gt;
&lt;li&gt;Prenez les congés dont vous avez besoin.&lt;/li&gt;
&lt;li&gt;Une &lt;a href=&quot;https://crew.vc/perspectives-insights/scaling-culture-through-hyper-growth/&quot;&gt;culture&lt;/a&gt; du travail où :&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;Vous travaillerez aux côtés de personnes du monde entier qui reflètent les valeurs de MaintainX : Intelligents, Humbles, Optimistes.&lt;/li&gt;
&lt;li&gt;Nous croyons en la méritocratie, où les idées et les efforts sont publiquement célébrés.&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qui sommes-nous:&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;Notre mission est d’offrir une plateforme unique aux équipes de maintenance, de réparation et d’exploitation afin de maintenir le monde physique en fonctionnement. Nous croyons que le plus grand atout d’une organisation, ce sont les personnes qui en font partie. C’est pourquoi nous avons conçu une solution intuitive, axée sur le mobile, pour favoriser la productivité et la collaboration entre les équipes et les différents sites.&lt;/p&gt;
&lt;p&gt;MaintainX s&#39;engage à créer un environnement diversifié. Tous les candidats qualifiés seront pris en considération pour un emploi sans considération de race, de couleur, de religion, de sexe, d&#39;identité ou d&#39;expression de genre, d&#39;orientation sexuelle, d&#39;origine nationale, de génétique, d&#39;invalidité, d&#39;âge ou de statut d&#39;ancien combattant.&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;MaintainX est la première plateforme mobile de gestion des procédures pour les travailleurs de l&#39;industrie et les travailleurs de première ligne. Nous construisons le GitHub pour les procédures de travail réelles telles que la maintenance, la sécurité et les opérations, et nous améliorons l&#39;efficacité opérationnelle de plus de 12,000+ entreprises, dont Duracell, Univar Solutions Inc., Titan America, McDonalds, Brenntag, Cintas, Michaels, and Shell.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Nous avons récemment conclu un financement de série D de 150 millions de dollars, ce qui porte notre financement total à 254 millions de dollars et valorise l&#39;entreprise à 2,5 milliards de dollars.&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Nous recherchons un développeur Full Stack pour rejoindre ces équipes. Ces rôles ont des ouvertures pour des postes de niveau intermédiaire, senior et leader.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Ce que vous ferez :&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous réfléchirez et collaborerez avec les Gestionnaires de Produit et les Designers pour conceptualiser de nouvelles fonctionnalités et serez impliqué dans l&#39;élaboration des roadmaps du produits.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous apporterez un état d&#39;esprit produit pour comprendre l&#39;activité des clients, leurs besoins, et les opportunités et défis techniques qui existent dans leurs secteurs d&#39;activité.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;br&gt;Vous travaillerez sur l&#39;ensemble de notre stack (TypeScript, React, React Native, Node.js, et GraphQL) - Web et Mobile.&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous travaillerez avec l&#39;équipe pour construire, maintenir et optimiser les fonctionnalités du produit qui se concentrent sur la façon dont nos utilisateurs collaborent le mieux les uns avec les autres.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous serez activement responsable des fonctionnalités ou des systèmes de l&#39;équipe et définirez leur santé à long terme, tout en améliorant la santé des systèmes environnants.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous encadrerez d&#39;autres ingénieurs et révisez le code en profondeur.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous améliorerez les normes, les outils et les processus d&#39;ingénierie et apporterez les meilleures pratiques en matière de planification, de développement, de test et de déploiement d&#39;un code conforme à l&#39;industrie.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Être sur appel&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;À propos de vous:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous avez 3 à 5 ans d&#39;expérience professionnelle dans le développement de logiciels full-stack, Vous avez de l&#39;expérience dans la construction de produits logiciels basés sur le web et le mobile, plus particulièrement avec TypeScript, les bases de données SQL, React et Node.js.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous avez de l&#39;expérience dans le développement web itératif et responsive mobile-first.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous écrivez du code compréhensible et testable, avec un œil sur la maintenabilité.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous êtes un excellent communicateur : expliquer des concepts techniques complexes aux designers, au soutien technique et aux autres développeurs n&#39;est pas un problème pour vous.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous avez démontré votre expérience dans un environnement en constante évolution.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Une attention particulière est accordée aux candidats présentant les caractéristiques suivantes:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Un diplôme en développement web, en informatique ou dans un domaine connexe.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Connaissance de React Native.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Connaissance de GraphQL.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Expérience avec les fournisseurs de cloud (AWS/Azure/GCP, etc.) et le déploiement de services.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Quels sont les avantages pour vous?:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Un salaire compétitif et des opportunités d&#39;équité significatives.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Couverture des soins de santé, des soins dentaires et des soins de la vue.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Programme d&#39;inscription 401(k) / RRSP.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Prenez les congés dont vous avez besoin.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Une &lt;a href=&quot;https://crew.vc/perspectives-insights/scaling-culture-through-hyper-growth/&quot;&gt;culture&lt;/a&gt; du travail où :&lt;/span&gt;&lt;/li&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Vous travaillerez aux côtés de personnes du monde entier qui reflètent les principes de MaintainX : Intelligents, Humbles, Optimistes.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Nous croyons en la méritocratie, où les idées et les efforts sont publiquement célébrés.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;Qui sommes-nous:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;div&gt;
&lt;div class=&quot;_root_6brvb_1 _parentHover_1pu4j_9&quot;&gt;
&lt;div class=&quot;_commentBody_6brvb_28&quot;&gt;
&lt;div class=&quot;_commentBodyText_yqhtb_1 _breakWord_89j05_23 global_breakWord&quot; data-test=&quot;MessageThreadRow.Message&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Notre mission est d’offrir une plateforme centralisée pour la maintenance, les réparations et les opérations, afin de faire tourner le monde physique sans interruption. Nous croyons que le plus grand atout d’une organisation, ce sont les personnes qui en font partie. C’est pourquoi nous avons conçu une solution intuitive mobile, pour favoriser la productivité et la collaboration entre les équipes et les différents sites.&lt;/span&gt;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;MaintainX s&#39;engage à créer un environnement diversifié. Tous les candidats qualifiés seront pris en considération pour un emploi sans tenir compte de la race, de la couleur, de la religion, du sexe, de l&#39;identité ou de l&#39;expression sexuelle, de l&#39;orientation sexuelle, de l&#39;origine nationale, de la génétique, du handicap, de l&#39;âge ou du statut d&#39;ancien combattant.&lt;/span&gt;&lt;/p&gt;

&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;em&gt;MaintainX is the leading AI-powered Enterprise Asset Management (EAM) platform built for the modern world. Our mission is to make the lives of blue-collar workers easier worldwide by providing intuitive, mobile-first software that helps teams keep the physical world running. MaintainX powers operational excellence for 12,000+ businesses including Duracell, Univar Solutions Inc., Titan America, McDonald&#39;s, Brenntag, Cintas, Xylem, and Shell.&amp;nbsp;We recently completed a $150 million Series D round, bringing our total funding to $254 million and valuing the company at $2.5 billion.&amp;nbsp;We’re redefining how maintenance and operations teams work—transforming maintenance from a cost center into a strategic lever for growth&lt;strong&gt;.&lt;/strong&gt; MaintainX fuses enterprise strength with consumer simplicity, empowering organizations to boost reliability, performance, and efficiency.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;The Opportunity&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;We&#39;re looking for a Director of Engineering to lead MaintainX&#39;s Platform division — the seven foundational teams every product engineer builds on: AI Builder, DevOps, Compliance, Testing Frameworks, Backend Frameworks, Mobile Frameworks, and SRE. This is a manager-of-managers role for someone who wants to define how a high-growth engineering org operates at scale.&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;What You’ll Do:&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Own the roadmap and operating model for Platform Engineering: set division-level priorities, manage cross-team dependencies, and translate business goals into multi-quarter platform investments.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Lead and develop a team of Software Engineering Managers - coaching on people development, technical judgment, and organizational effectiveness across seven teams.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Set the engineering standards every product team depends on: framework conventions, reliability targets, compliance posture, and CI/CD health.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Drive MaintainX&#39;s AI-native platform strategy - the AI Builder team&#39;s agent orchestration, tool registry, and developer environments sit in this division; your job is to ensure the org extracts real leverage from them.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Own division-level reliability: SLO definitions, incident response frameworks, on-call health, and the systemic path from incident to prevention.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Partner with the CTO and peer engineering leaders on org design, architectural decisions, and headcount planning.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Represent Platform Engineering to the business — translating infrastructure investment into engineering velocity, developer experience, and customer trust.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;br&gt;About You:&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;10+ years in software engineering with 5+ years in engineering leadership, including 2+ years managing managers across multiple teams.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Technical depth in at least two of: distributed systems, backend or mobile frameworks, platform engineering, reliability engineering - credible enough to make hard hiring decisions and engage in architecture reviews.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Track record of owning platform or infrastructure-focused teams at a growth-stage B2B SaaS company, with demonstrated impact on engineering velocity.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;AI-forward: you set direction for teams building on LLMs and agentic workflows, and you hold your org to an AI-native standard.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Systems thinker who identifies organizational bottlenecks and eliminates them without creating new ones — you design teams, not just manage them.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Strong communicator who can represent platform complexity and tradeoffs clearly to product, finance, and executive stakeholders.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;br&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Nice to Have:&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experience leading a Testing Frameworks, Quality Engineering, or Developer Productivity platform function.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Hands-on history scaling developer platforms through rapid headcount growth (Series D+).&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Familiarity with CMMS, IoT, or industrial SaaS domains.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;br&gt;What’s in it for you:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Competitive salary and meaningful equity opportunities.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Healthcare, dental, and vision coverage.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;401(k) / RRSP enrollment program.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Take what you need PTO.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;A Work &lt;a href=&quot;https://crew.vc/perspectives-insights/scaling-culture-through-hyper-growth/&quot;&gt;Culture&lt;/a&gt; where:&lt;/span&gt;&lt;/li&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;You’ll work alongside folks across the globe that reflect the MaintainX values: Smart Humble Optimists.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;We believe in meritocracy, where ideas and effort are publicly celebrated.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;hr&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;strong&gt;About Us:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;em&gt;Our mission is to make the life of blue-collar workers easier worldwide by creating software that meets their needs and realities. Our product is truly life-changing for that 80% of the workforce who doesn’t work behind a desk and needs enterprise-grade software at their fingertips.MaintainX is committed to creating a diverse environment. All qualified applicants will receive consideration for employment without regard to race, color, religion, gender, gender identity or expression, sexual orientation, national origin, genetics, disability, age, or veteran status.&lt;/em&gt;&lt;/span&gt;&lt;br&gt;&lt;br&gt;&lt;/p&gt;

